INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39311, 'Hosea 4:15', 'Hosea', 4, 15, 'که څه هم تاسو اسراییلیان زنا کوئ، خو د یهودا د ګناه سبب مه کېږئ. جلجال یا بیت‌آون ته د عبادت دپاره مه ځئ او هلته د ژوندي څښتن په نوم قسم مه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_15.mp3', '', 1761754199, 1761754199),
(39312, 'Hosea 4:16', 'Hosea', 4, 16, 'د اسراییلو خلک د غویي په شان سرتمبه خلک دي. ایا څښتن کولای شي چې هغوی لکه د وریو په شان په څړځایونو کې ماړه کړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_16.mp3', '', 1761754199, 1761754199),
(39313, 'Hosea 4:17', 'Hosea', 4, 17, 'د اسراییلو خلک د بتانو سره یوځای شوي دي. پرېږده چې هغوی په خپله لاره روان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_17.mp3', '', 1761754199, 1761754199),
(39314, 'Hosea 4:18', 'Hosea', 4, 18, 'کله چې هغوی زیات شراب وڅښي، نو فاحشو پسې ورځي او د عزت څخه بې‌عزتي غوره ګڼي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_18.mp3', '', 1761754199, 1761754199),
(39315, 'Hosea 4:19', 'Hosea', 4, 19, 'هغوی به داسې ورک شي لکه باد یې چې یوسي او بتانو ته د قربانیو په وړاندې کولو باندې به وشرمیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_19.mp3', '', 1761754199, 1761754199),
(39316, 'Leviticus 14:1', 'Leviticus', 14, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_1.mp3', '', 1761754199, 1761754199),
(39317, 'Leviticus 14:2', 'Leviticus', 14, 2, '«دا قوانین د هغه کس د پاکېدلو په اړه دي چې د پوستکي د ساري ناروغۍ څخه روغ شوی وي. په هغه ورځ چې د هغه پاکوالی اعلانیږي، باید هغه کاهن ته راوستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_2.mp3', '', 1761754199, 1761754199),
(39318, 'Leviticus 14:3', 'Leviticus', 14, 3, 'کاهن دې د کمپ څخه دباندې لاړ شي او هغه دې معاینه کړي. که چېرې هغه کس د پوستکي د ساري ناروغۍ څخه روغ شوی وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_3.mp3', '', 1761754199, 1761754199),
(39319, 'Leviticus 14:4', 'Leviticus', 14, 4, 'کاهن به داسې حکم وکړي چې دوه ژوندۍ پاکې مرغۍ، د سبر لږ لرګي، سور تار او د وېلني بوټی دې د پاکوالي د مراسمو دپاره راوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_4.mp3', '', 1761754199, 1761754199),
(39320, 'Leviticus 14:5', 'Leviticus', 14, 5, 'بیا به کاهن داسې حکم وکړي چې د دې مرغیو څخه دې یوه د خټو د لوښي دپاسه چې د چینې تازه اوبه په کې وي، حلاله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_5.mp3', '', 1761754199, 1761754199),
(39321, 'Leviticus 14:6', 'Leviticus', 14, 6, 'هغه دې بله ژوندۍ مرغۍ د سبر د لرګي، سور تار او د وېلني د بوټي سره واخلي او د هغې مرغۍ په وینه کې دې غوټه کړي چې د تازه اوبو دپاسه حلاله شوې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_6.mp3', '', 1761754199, 1761754199),
(39322, 'Leviticus 14:7', 'Leviticus', 14, 7, 'کاهن به اووه ځلې په هغه کس باندې چې د ساري ناروغۍ څخه پاکیږي، هغه وینه وشیندي او هغه به پاک اعلان کړي. بیا دې هغه ژوندۍ مرغۍ په صحرا کې خوشې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_7.mp3', '', 1761754199, 1761754199),
(39323, 'Leviticus 14:8', 'Leviticus', 14, 8, 'کوم کس چې پاکیږي، هغه باید خپل کالي ووینځي، خپل ټول ویښتان دې وخرایي او غسل دې وکړي، بیا به هغه پاک شي. له دې وروسته هغه کولای شي چې کمپ ته ورننوځي، خو اووه ورځې باید د خپلې خېمې څخه دباندې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_8.mp3', '', 1761754199, 1761754199),
(39324, 'Leviticus 14:9', 'Leviticus', 14, 9, 'هغه باید په اوومه ورځ بیا خپل سر، ږیره، وروځې او د بدن پاتې ویښتان وخرایي. خپل کالي دې ووینځي او غسل دې وکړي، نو هغه به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_9.mp3', '', 1761754199, 1761754199),
(39325, 'Leviticus 14:10', 'Leviticus', 14, 10, 'هغه باید په اتمه ورځ دغه شیان راوړي: دوه وري او یوه یو کلنه مېږه چې هېڅ عیب په کې نه وي، د غلې دانې د نذرانې دپاره درې کیلو ګرامه ښه اوړه چې د زیتونو تېل ورسره ګډ وي او یوه پیاله د زیتونو تېل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_10.mp3', '', 1761754199, 1761754199),
(39326, 'Leviticus 14:11', 'Leviticus', 14, 11, 'کاهن باید هغه کس چې پاکیږي، د دې نذرانو سره د سپېڅلې خېمې د دروازې په خوله کې د څښتن حضور ته ورولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_11.mp3', '', 1761754199, 1761754199),
(39327, 'Leviticus 14:12', 'Leviticus', 14, 12, 'بیا به کاهن یو وری د یوې پیالې تېلو سره واخلي او هغه به د تاوان د نذرانې په توګه وړاندې کړي. کاهن به هغه پورته ونیسي، ترڅو دا وښایي چې هغه څښتن ته وقف شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_12.mp3', '', 1761754199, 1761754199),
(39328, 'Leviticus 14:13', 'Leviticus', 14, 13, 'هغه دې وری په هغه سپېڅلي ځای کې حلال کړي چې د ګناه د نذرانو او سوځېدونکو نذرانو دپاره حیوانات حلالیږي. هغه باید داسې وکړي، ځکه چې د تاوان نذرانه د ګناه د نذرانې په شان د کاهن ده او هغه ډېره سپېڅلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_13.mp3', '', 1761754199, 1761754199),
(39329, 'Leviticus 14:14', 'Leviticus', 14, 14, 'کاهن دې د وري د وینې څخه لږه وینه واخلي او د هغه کس چې پاکیږي، د هغه د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې دې وسولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_14.mp3', '', 1761754199, 1761754199),
(39330, 'Leviticus 14:15', 'Leviticus', 14, 15, 'بیا به کاهن لږ تېل راواخلي او د خپل چپ لاس په ورغوي کې به یې توی کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_15.mp3', '', 1761754199, 1761754199),
(39331, 'Leviticus 14:16', 'Leviticus', 14, 16, 'خپله ښي ګوته به په خپل ورغوي کې غوټه کړي او لږ تېل به په خپلې ګوتې سره د څښتن په حضور کې اووه ځلې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_16.mp3', '', 1761754199, 1761754199),
(39332, 'Leviticus 14:17', 'Leviticus', 14, 17, 'کاهن دې لږ تېل چې د هغه د لاس په ورغوي کې پاتې دي، راواخلي او د هغه کس چې پاکیږي د هغه د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې وسولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_17.mp3', '', 1761754199, 1761754199),
(39333, 'Leviticus 14:18', 'Leviticus', 14, 18, 'کاهن به پاتې تېل چې د هغه په ورغوي کې دي، د هغه چا په سر باندې توی کړي چې پاکیږي او د هغه دپاره به د څښتن په حضور کې کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_18.mp3', '', 1761754199, 1761754199),
(39334, 'Leviticus 14:19', 'Leviticus', 14, 19, 'بیا دې کاهن د ګناه نذرانه قرباني کړي او د هغه چا دپاره دې کفاره ادا کړي چې د خپلې ناپاکۍ څخه پاکیږي. له هغې وروسته به د سوځېدونکې نذرانې دپاره حیوان حلال کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_19.mp3', '', 1761754199, 1761754199),
(39335, 'Leviticus 14:20', 'Leviticus', 14, 20, 'او د غلې دانې د نذرانې سره به یې د قربانۍ په ځای باندې وړاندې کړي. په دې ډول به د هغه کس دپاره کفاره ادا کړي او هغه به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_20.mp3', '', 1761754199, 1761754199),
(39336, 'Leviticus 14:21', 'Leviticus', 14, 21, 'که چېرې هغه کس غریب وي او نور څه نه شي اخیستلی، باید یو وری د تاوان د نذرانې په توګه راوړي. کاهن به هغه څښتن ته د وقف کولو دپاره پورته ونیسي او د هغه کس دپاره به کفاره ادا کړي. هغه به یو کیلو ګرام ښه اوړه چې د زیتونو تېل ورسره ګډ وي، د غلې دانې د نذرانې دپاره راوړي او یوه پیاله تېل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_21.mp3', '', 1761754199, 1761754199),
(39337, 'Leviticus 14:22', 'Leviticus', 14, 22, 'همدارنګه هغه کس به دوه کوترې یا دوه قمري ګانې راوړي، یوه د ګناه د نذرانې دپاره او بله د سوځېدونکې نذرانې دپاره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_22.mp3', '', 1761754199, 1761754199),
(39338, 'Leviticus 14:23', 'Leviticus', 14, 23, 'هغه باید په اتمه ورځ دا شیان د خپل ځان د پاکېدلو دپاره د سپېڅلې خېمې د دروازې په خوله کې کاهن ته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_23.mp3', '', 1761754199, 1761754199),
(39339, 'Leviticus 14:24', 'Leviticus', 14, 24, 'کاهن به وری او د زیتونو تېل د تاوان د نذرانې دپاره واخلي او څښتن ته به یې د وقف کولو دپاره پورته ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_24.mp3', '', 1761754199, 1761754199),
(39340, 'Leviticus 14:25', 'Leviticus', 14, 25, 'هغه به وری د تاوان د نذرانې په توګه حلال کړي او د هغه لږه وینه به واخلي او د هغه کس چې پاکیږي، د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې به یې وسولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_25.mp3', '', 1761754199, 1761754199),
(39341, 'Leviticus 14:26', 'Leviticus', 14, 26, 'بیا دې کاهن لږ تېل راواخلي او د خپل چپ لاس په ورغوي کې دې توی کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_26.mp3', '', 1761754199, 1761754199),
(39342, 'Leviticus 14:27', 'Leviticus', 14, 27, 'هغه دې په خپله ښي ګوته د خپل ورغوي څخه لږ تېل اووه ځلې د څښتن په حضور کې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_27.mp3', '', 1761754199, 1761754199),
(39343, 'Leviticus 14:28', 'Leviticus', 14, 28, 'د خپل ورغوي څخه دې لږ تېل په هماغو ځایونو باندې وسولوي چې د تاوان د نذرانې وینه یې ورباندې سولولې وه، یعنې د هغه کس چې پاکیږي د هغه د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې دې هغه وسولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_28.mp3', '', 1761754199, 1761754199),
(39344, 'Leviticus 14:29', 'Leviticus', 14, 29, 'کاهن به هغه تېل چې د هغه په ورغوي کې پاتې دي، د هغه کس په سر باندې چې پاکیږي، توی کړي او په دې ډول به د هغه دپاره د څښتن په حضور کې کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_29.mp3', '', 1761754199, 1761754199),
(39345, 'Leviticus 14:32', 'Leviticus', 14, 32, 'دا مقررات د هغه چا دپاره دي چې د پوستکي په ساري ناروغۍ باندې اخته وي او د خپل ځان د پاکوالي دپاره هغه نذرانې چې رواج وې، نه شي اخیستلی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_32.mp3', '', 1761754199, 1761754199),
(39346, 'Leviticus 14:33', 'Leviticus', 14, 33, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_33.mp3', '', 1761754199, 1761754199),
(39347, 'Leviticus 14:34', 'Leviticus', 14, 34, '«کله چې تاسو د کنعان خاورې ته چې تاسو ته یې ستاسو د ملکیت په توګه درکوم، ورننوځئ او که چېرې په تاسو کې څوک په یو کور کې یوه چڼاسکه چې ما درلېږلې ده پیدا کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_34.mp3', '', 1761754199, 1761754199),
(39348, 'Leviticus 14:35', 'Leviticus', 14, 35, 'نو د هغه کور خاوند باید لاړ شي او کاهن ته دې داسې ووایي چې ما په خپل کور کې یو شی لیدلی دی چې د چڼاسکې په شان ښکاري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_35.mp3', '', 1761754199, 1761754199),
(39349, 'Leviticus 14:36', 'Leviticus', 14, 36, 'کاهن به داسې حکم وکړي چې مخکې له دې چې هغه د چڼاسکې د معاینه کولو دپاره لاړ شي، هرڅه دې د هغه کور څخه راوویستل شي. که نه، نو هرڅه چې په هغه کور کې دي، هغه به ناپاکه اعلان شي. له هغې وروسته دې کاهن دننه لاړ شي او کور دې معاینه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_36.mp3', '', 1761754199, 1761754199),
(39350, 'Leviticus 14:37', 'Leviticus', 14, 37, 'هغه دې په دېوالونو باندې چڼاسکې معاینه کړي. که چېرې په هغه کې شین بخن یا سوربخن داغونه وي چې دېوال خرابوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_37.mp3', '', 1761754199, 1761754199),
(39351, 'Leviticus 14:38', 'Leviticus', 14, 38, 'نو کاهن به د هغه کور څخه لاړ شي او کور به د اوو ورځو دپاره بند کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_38.mp3', '', 1761754199, 1761754199),
(39352, 'Leviticus 14:39', 'Leviticus', 14, 39, 'په اوومه ورځ به کاهن بېرته راشي او هغه کور به بیا معاینه کړي. که چېرې چڼاسکه په دېوالونو باندې خپره شوې وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_39.mp3', '', 1761754199, 1761754199),
(39353, 'Leviticus 14:40', 'Leviticus', 14, 40, 'هغه دې حکم وکړي چې هغه تیږې چې چڼاسکې ورباندې پیدا شوې دي، هغه دې لېرې شي او د ښار څخه دې دباندې په یو ناپاک ځای کې وغورځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_40.mp3', '', 1761754199, 1761754199),
(39354, 'Leviticus 14:41', 'Leviticus', 14, 41, 'له هغې وروسته باید کاهن ټول دننني دېوالونه په یو چا باندې وتوږي او خاوره دې د ښار څخه دباندې په یو ناپاکه ځای کې وغورځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_41.mp3', '', 1761754199, 1761754199),
(39355, 'Leviticus 14:42', 'Leviticus', 14, 42, 'بیا دې د هغو تیږو په ځای چې لېرې کړای شوې دي د نورو تیږو څخه کار واخیستل شي او دېوالونو ته دې نوی اخېړ ورکړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_42.mp3', '', 1761754199, 1761754199),
(39356, 'Leviticus 14:43', 'Leviticus', 14, 43, 'که چېرې د دېوالونو د تیږو د لېرې کولو، توږلو او اخېړولو نه وروسته بیا په هغه کور کې چڼاسکه راښکاره شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_43.mp3', '', 1761754199, 1761754199),
(39357, 'Leviticus 14:44', 'Leviticus', 14, 44, 'نو کاهن دې لاړ شي او هغه دې بیا معاینه کړي. که چېرې په کور کې چڼاسکه خپره شوې وي، نو دا یوه خرابوونکې چڼاسکه ده او دا کور ناپاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_44.mp3', '', 1761754199, 1761754199),
(39358, 'Leviticus 14:45', 'Leviticus', 14, 45, 'هغه کور باید وران شي او د هغه تیږې، تیرونه او ټوله خاوره باید د ښار څخه دباندې یو ناپاکه ځای ته یووړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_45.mp3', '', 1761754199, 1761754199),
(39359, 'Leviticus 14:46', 'Leviticus', 14, 46, 'په هغه دوران کې چې کاهن هغه کور بند اعلان کړی وي، نو هرڅوک چې هغه ته ننوځي، هغه به تر ماښامه پورې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_46.mp3', '', 1761754199, 1761754199),
(39360, 'Leviticus 14:47', 'Leviticus', 14, 47, 'همدارنګه هرڅوک چې په هغه کور کې خوب کوي یا خوراک کوي، باید خپل کالي ووینځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_47.mp3', '', 1761754199, 1761754199),
(39361, 'Leviticus 14:48', 'Leviticus', 14, 48, 'خو که چېرې کاهن راشي او هغه معاینه کړي، نو که د کور د اخېړولو څخه وروسته چڼاسکه خپره شوې نه وي، نو هغه به کور پاک اعلان کړي، ځکه چې چڼاسکه ورکه شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_48.mp3', '', 1761754199, 1761754199),
(39362, 'Leviticus 14:49', 'Leviticus', 14, 49, 'هغه دې د کور د پاکولو دپاره دوه مرغۍ، د سبر لرګی، سور تار او د وېلني بوټی راواخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_49.mp3', '', 1761754199, 1761754199),
(39363, 'Leviticus 14:50', 'Leviticus', 14, 50, 'هغه به د دغو مرغیو څخه یوه د خټو د لوښي دپاسه چې د چینې تازه اوبه په کې وي، حلاله کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_50.mp3', '', 1761754199, 1761754199),
(39364, 'Leviticus 14:51', 'Leviticus', 14, 51, 'بیا دې د سبر لرګی، د وېلني بوټی، سور تار او ژوندۍ مرغۍ راواخلي او هغه دې د مړې مرغۍ په وینه او تازه اوبو کې غوټه کړي او په کور باندې دې اووه ځلې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_51.mp3', '', 1761754199, 1761754199),
(39365, 'Leviticus 14:52', 'Leviticus', 14, 52, 'په دې ډول به کاهن هغه کور د مرغۍ په وینه، تازه اوبو، ژوندۍ مرغۍ، د سبر په لرګي، د وېلني په بوټي او سور تار باندې پاک کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_52.mp3', '', 1761754199, 1761754199),
(39366, 'Leviticus 14:53', 'Leviticus', 14, 53, 'بیا دې هغه ژوندۍ مرغۍ د ښار څخه دباندې په صحرا کې خوشې کړي. په دې ډول به هغه د کور دپاره د پاکوالي مراسم سرته ورسوي او هغه به پاک شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_53.mp3', '', 1761754199, 1761754199),
(39367, 'Leviticus 14:54', 'Leviticus', 14, 54, 'دا مقررات د پوستکي د هرې ساري ناروغۍ دپاره دي لکه خارښت،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_54.mp3', '', 1761754199, 1761754199),
(39368, 'Leviticus 14:57', 'Leviticus', 14, 57, 'د دې مقرراتو له مخې دا پرېکړه کېدای شي چې یو شی په کوم وخت کې پاک دی او په کوم وخت کې ناپاک.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus14_verse_57.mp3', '', 1761754199, 1761754199),
(39369, 'Exodus 35:1', 'Exodus', 35, 1, 'موسی د اسراییلو ټول قوم سره راټول کړ او ورته ویې ویل: «دا د څښتن حکمونه دي چې تاسو به ورباندې عمل کوئ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_1.mp3', '', 1761754199, 1761754199),
(39370, 'Exodus 35:2', 'Exodus', 35, 2, 'تاسو باید په هفته کې شپږ ورځې کار وکړئ، خو په اوومه ورځ چې د څښتن سپېڅلې ورځ ده، ارام وکړئ. هرڅوک چې په هغې ورځ کار وکړي، هغه دې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_2.mp3', '', 1761754199, 1761754199),
(39371, 'Exodus 35:3', 'Exodus', 35, 3, 'حتی د سبت په ورځ په خپلو کورونو کې اور هم مه بلوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_3.mp3', '', 1761754199, 1761754199),
(39372, 'Exodus 35:4', 'Exodus', 35, 4, 'موسی د اسراییلو ټول قوم ته وویل: «څښتن داسې حکم کړی دی:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_4.mp3', '', 1761754199, 1761754199),
(39373, 'Exodus 35:5', 'Exodus', 35, 5, 'څه چې تاسو لرئ د هغو څخه د څښتن دپاره یوه نذرانه یوسئ. هرڅوک چې په خپله خوښه څښتن ته نذرانې راوړي، نو دا شیان دې راوړي: سره زر، سپین زر او برنج،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_5.mp3', '', 1761754199, 1761754199),
(39374, 'Exodus 35:6', 'Exodus', 35, 6, 'ښه کتان او ابي، بانجاني او سرې وړۍ، هغه ټوکر چې د وزو د وړیو څخه جوړ شوی وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_6.mp3', '', 1761754199, 1761754199),
(39375, 'Exodus 35:7', 'Exodus', 35, 7, 'سره رنګ شوي د پسه پوستکي، ښه څرمن، د اکاسۍ لرګی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_7.mp3', '', 1761754199, 1761754199),
(39376, 'Exodus 35:8', 'Exodus', 35, 8, 'د څراغونو دپاره تېل، د مسح کولو د تېلو او د خوشبویۍ دپاره مسالې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_8.mp3', '', 1761754199, 1761754199),
(39377, 'Exodus 35:9', 'Exodus', 35, 9, 'د عقیقو تیږې او نورې قیمتي تیږې چې د لوی کاهن په سپېڅلي پېشبند او د هغه په سینه پوښ باندې ولګول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_9.mp3', '', 1761754199, 1761754199),
(39378, 'Exodus 35:10', 'Exodus', 35, 10, 'په تاسو کې چې څومره ماهر خلک دي، هغوی دې راشي او هغه ټول شیان دې جوړ کړي چې څښتن یې حکم کړی دی:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_10.mp3', '', 1761754199, 1761754199),
(39379, 'Exodus 35:11', 'Exodus', 35, 11, 'لکه سپېڅلې خېمه او د هغې پوښونه، چنګکونه، چوکاټونه، اړمونه، ستنې او پایې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_11.mp3', '', 1761754199, 1761754199),
(39380, 'Exodus 35:12', 'Exodus', 35, 12, 'د لوظ صندوق او د هغه میلې او سرپوښ چې کفاره ورباندې ادا کیږي او پرده چې هغه ورباندې پټیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_12.mp3', '', 1761754199, 1761754199),
(39381, 'Exodus 35:13', 'Exodus', 35, 13, 'مېز د پایو او ټول سامان سره او سپېڅلې ډوډۍ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_13.mp3', '', 1761754199, 1761754199),
(39382, 'Exodus 35:14', 'Exodus', 35, 14, 'د رڼا دپاره څراغدان د هغه د سامان سره، د رڼا دپاره څراغونه او تېل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_14.mp3', '', 1761754199, 1761754199),
(39383, 'Exodus 35:15', 'Exodus', 35, 15, 'د خوشبویۍ د سوځولو د قربانۍ ځای د هغې د میلو سره، د مسح کولو تېل او خوشبویي، د سپېڅلې خېمې د دروازې دپاره پرده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_15.mp3', '', 1761754199, 1761754199),
(39384, 'Exodus 35:16', 'Exodus', 35, 16, 'د سوځېدونکې نذرانې د قربانۍ ځای او د هغه برنجي جالۍ، میلې او ټول لوښي، برنجي تشت د پایې سره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_16.mp3', '', 1761754199, 1761754199),
(39385, 'Exodus 35:17', 'Exodus', 35, 17, 'د حوېلۍ پردې د هغو د ستنو او پایو سره او د حوېلۍ د دروازې دپاره پرده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_17.mp3', '', 1761754199, 1761754199),
(39386, 'Exodus 35:18', 'Exodus', 35, 18, 'د خېمې او حوېلۍ دپاره موږي او رسۍ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_18.mp3', '', 1761754199, 1761754199),
(39387, 'Exodus 35:19', 'Exodus', 35, 19, 'ښکلي کالي چې په سپېڅلي ځای کې د خدمت دپاره اغوستل کیږي، د هارون کاهن دپاره ځانګړي کالي او د هغه د زامنو دپاره کالي چې د کاهنۍ د خدمت په وخت کې یې اغوندي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_19.mp3', '', 1761754199, 1761754199),
(39388, 'Exodus 35:20', 'Exodus', 35, 20, 'بیا د اسراییلو ټول خلک د موسی د حضور څخه لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_20.mp3', '', 1761754199, 1761754199),
(39389, 'Exodus 35:21', 'Exodus', 35, 21, 'بیا هغو خلکو چې زړونو یې غوښتل چې څښتن ته نذرانې راوړي، نو هغه یې راوړلې چې په سپېڅلې خېمه، د عبادت په خدمتونو او د کاهنانو د کالیو په جوړولو کې ورڅخه کار واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_21.mp3', '', 1761754199, 1761754199),
(39390, 'Exodus 35:22', 'Exodus', 35, 22, 'نو ټول خلک یعنې نارینه او ښځې په خپله خوښه راغلل او هغوی د سینې ګلان، غوږوالۍ، ګوتې او غاړه کۍ او هر ډول د سرو زرو ګاڼې راوړلې او څښتن ته یې وقف کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_22.mp3', '', 1761754199, 1761754199),
(39391, 'Exodus 35:23', 'Exodus', 35, 23, 'د هرچا سره چې ابي، بانجاني یا سرې وړۍ، ښه کتان، د وزو د وړیو څخه جوړ شوی ټوکر، سره رنګ شوي د پسه پوستکي یا ښې څرمنې وې، هغه یې راوړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_23.mp3', '', 1761754199, 1761754199),
(39392, 'Exodus 35:24', 'Exodus', 35, 24, 'د چا سره چې سپین زر یا برنج او یا د اکاسۍ لرګي وو، هغه یې راوړل او څښتن ته یې د سوغات په توګه وړاندې کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_24.mp3', '', 1761754199, 1761754199),
(39393, 'Exodus 35:25', 'Exodus', 35, 25, 'هغو ټولو ښځو چې د ګنډلو او اوبدلو په کار کې یې مهارت درلود ابي، بانجاني یا سرې وړۍ یا ښه کتان چې هغوی په خپله جوړ کړي وو، راوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_25.mp3', '', 1761754199, 1761754199),
(39394, 'Exodus 35:26', 'Exodus', 35, 26, 'ټولو ښځو چې زړونو یې غوښتل او مهارت یې درلود، هغوی به د وزو د وړیو څخه تارونه جوړول او اوبدل به یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_26.mp3', '', 1761754199, 1761754199),
(39395, 'Exodus 35:27', 'Exodus', 35, 27, 'مشرانو د عقیقو تیږې او نور غمي راوړل چې په سپېڅلي پېشبند او سینه پوښ باندې ولګول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_27.mp3', '', 1761754199, 1761754199),
(39396, 'Exodus 35:28', 'Exodus', 35, 28, 'همدارنګه هغوی د څراغونو دپاره تېل راوړل او خوشبویه مسالې یې راوړلې چې د خوشبویۍ او مسح کولو د تېلو سره ګډ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_28.mp3', '', 1761754199, 1761754199),
(39397, 'Exodus 35:29', 'Exodus', 35, 29, 'د اسراییلو ټولو نارینه او ښځو چې غوښتل یې د هغه کار دپاره د خپلې خوښې نذرانې راوړلې چې څښتن د موسی په وسیله هغوی ته حکم کړی ؤ، چې هغه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_29.mp3', '', 1761754199, 1761754199),
(39398, 'Exodus 35:30', 'Exodus', 35, 30, 'بیا موسی اسراییلیانو ته وویل: «ګورئ، څښتن بزل ییل د اوري زوی او د حور لمسی د یهودا له قبیلې څخه غوره کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_30.mp3', '', 1761754199, 1761754199),
(39399, 'Exodus 35:31', 'Exodus', 35, 31, 'څښتن هغه د خپل روح څخه ډک کړی دی او په هر ډول هنري کار کې یې ورته مهارت، توان او پوهه ورکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_31.mp3', '', 1761754199, 1761754199),
(39400, 'Exodus 35:32', 'Exodus', 35, 32, 'هغه کولای شي چې د سرو زرو، سپینو زرو او برنجو څخه ښکلي شیان جوړ کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_32.mp3', '', 1761754199, 1761754199),
(39401, 'Exodus 35:33', 'Exodus', 35, 33, 'تیږې پرې کړي او تیارې یې کړي، د لرګیو کار او هر ډول هنري کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_33.mp3', '', 1761754199, 1761754199),
(39402, 'Exodus 35:34', 'Exodus', 35, 34, 'څښتن هغه او د دان د قبیلې د اخیسامک زوی اهولیاب دواړو ته دا توان ورکړی دی چې نورو ته خپل هنر ورزده کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_34.mp3', '', 1761754199, 1761754199),
(39403, 'Exodus 35:35', 'Exodus', 35, 35, 'هغه ورته په هر ډول کار کې مهارت ورکړی دی چې د زرګرانو، نقشه جوړوونکو، د ابي، بانجاني او سرو وړیو او د ښه کتان د ګلدوزانو او اوبدونکو په توګه کار وکړي. هغوی کولای شي چې هر ډول کارونه وکړي او هغوی تکړه نقشه جوړوونکي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus35_verse_35.mp3', '', 1761754199, 1761754199),
(39404, 'Malachi 1:1', 'Malachi', 1, 1, 'دا هغه پېغام دے کوم چې مالِک خُدائ د ملاکى په وسيله بنى اِسرائيلو له ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_1.mp3', '', 1761754199, 1761754199),
(39405, 'Malachi 1:2', 'Malachi', 1, 2, '”ما تاسو سره مينه کړې ده،“ مالِک خُدائ فرمائى. ”خو تاسو تپوس کوئ چې، تا مونږ سره څنګه مينه کړې ده؟“ مالِک خُدائ په جواب کښې وفرمائيل، ”آيا عِيسو د يعقوب ورور نۀ وو څۀ؟ بيا هم ما يعقوب سره مينه وکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_2.mp3', '', 1761754199, 1761754199),
(39406, 'Malachi 1:3', 'Malachi', 1, 3, 'خو عِيسو يعنې د ادوميانو پلار نيکۀ ما رد کړو، او ما د هغوئ غرونه شاړ کړل او د هغوئ ميراث مې د بيابان ګيدړانو ته پرېښودلو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_3.mp3', '', 1761754199, 1761754199),
(39407, 'Malachi 1:4', 'Malachi', 1, 4, 'ادوميان وائى چې، ”اګر کۀ مونږ تباه کړے شوى يُو، خو مونږ به دا کنډرې بيا جوړې کړُو.“ خو مالِک خُدائ ربُ الافواج دا فرمائى چې، ”هغوئ دا جوړولے شى، خو زۀ به يې تباه کړم. دې ته به د بدعملۍ مُلک وئيلے کيږى، او خلق به يې همېشه د خُدائ پاک د لعنت لاندې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_4.mp3', '', 1761754199, 1761754199),
(39408, 'Malachi 1:5', 'Malachi', 1, 5, 'کله چې تاسو دا تباهى په خپلو سترګو وګورئ نو وبه وايئ چې، مالِک خُدائ د اِسرائيل د سرحدونو نه بهر هم خپله لوئى ښکاره کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_5.mp3', '', 1761754199, 1761754199),
(39409, 'Malachi 1:6', 'Malachi', 1, 6, 'مالِک خُدائ ربُ الافواج اِمامانو ته فرمائى چې، ”يو زوئ د خپل پلار عزت کوى، او نوکر د خپل مالِک. کۀ چرې زۀ پلار يم، نو زما هغه عزت چرته دے؟ کۀ چرې زۀ مالِک يم، نو زما هغه احترام چرته دے؟ اے اِمامانو، خو دا تاسو يئ چې زما د نوم سپکاوے کوئ. خو تاسو تپوس کوئ چې، مونږ څنګه ستا د نوم سپکاوے کړے دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_6.mp3', '', 1761754199, 1761754199),
(39410, 'Malachi 1:7', 'Malachi', 1, 7, 'تاسو زما په قربان‌ګاه ناپاکه خوراک کېښودو. او بيا هم تاسو تپوس کوئ چې تۀ مونږ په څۀ ناپاک کړے يې؟ په دې چې تاسو ووئيل چې د مالِک خُدائ قربان‌ګاه ناپاکه ده زما د قربان ګاه سپکاوے مو وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi1_verse_7.mp3', '', 1761754199, 1761754199);